/**
 * Keep expo-audio available for in-app Focus tracks and completion sounds,
 * while removing its optional background/lock-screen playback service.
 *
 * Burrow deliberately stops audio when the app backgrounds and never calls
 * AudioPlayer.setActiveForLockScreen(). expo-audio still contributes a
 * MediaSessionService and FOREGROUND_SERVICE_MEDIA_PLAYBACK permission through
 * its library manifest, which makes Google Play require an inaccurate
 * foreground-media declaration. These `tools:node="remove"` markers survive
 * Gradle manifest merging and are regenerated by every Expo prebuild/EAS build.
 */
const { withAndroidManifest } = require('expo/config-plugins');

const MEDIA_PLAYBACK_PERMISSION =
  'android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK';
const AUDIO_CONTROLS_SERVICE =
  'expo.modules.audio.service.AudioControlsService';

const upsertRemoveMarker = (entries, androidName) => {
  const next = entries ?? [];
  const existing = next.find(
    (entry) => entry?.$?.['android:name'] === androidName,
  );

  if (existing) {
    existing.$['tools:node'] = 'remove';
    return next;
  }

  next.push({
    $: {
      'android:name': androidName,
      'tools:node': 'remove',
    },
  });
  return next;
};

const withForegroundAudioOnly = (config) =>
  withAndroidManifest(config, (config) => {
    const manifest = config.modResults.manifest;
    manifest.$['xmlns:tools'] =
      manifest.$['xmlns:tools'] ?? 'http://schemas.android.com/tools';

    manifest['uses-permission'] = upsertRemoveMarker(
      manifest['uses-permission'],
      MEDIA_PLAYBACK_PERMISSION,
    );

    const application = manifest.application?.[0];
    if (!application) {
      throw new Error('AndroidManifest.xml has no <application> element');
    }
    application.service = upsertRemoveMarker(
      application.service,
      AUDIO_CONTROLS_SERVICE,
    );

    return config;
  });

module.exports = withForegroundAudioOnly;
